  $j$[{"md5": "f609dcf5", "note": "the engine target as written; W1 names it by the sha256 prefix", "path": "ask627/w4/b1/target_engine_627.json", "source": "md5sum and sha256sum by W3; Wall 11818, 11829", "sha256_prefix": "86716be4"}, {"md5": "f0be61bd", "note": "the child target as written; W1 names it by the sha256 prefix", "path": "ask627/w4/b1/target_child_627.json", "source": "md5sum and sha256sum by W3; Wall 11818, 11829", "sha256_prefix": "5747ea34"}, {"md5": "f1cba0ed", "note": "build notes as they stand at 19:05 CST 2026-11-24, after W4 corrected the check count from 35 to 34 (commit 6fd0929c); 233f4192 was the md5 when draft 1 of this row was written, after W4 corrected the swapped hash labels (W1 N1); Wall 11815 names 61ea70da before that correction (a sha256 prefix by W1's N1; not recomputed by W3)", "path": "ask627/w4/b1/notes627.md", "commit": "fc81bf10 (before the correction)", "source": "md5sum by W3; Wall 11815, 11818, 11819"}, {"md5": "5ec685c0", "note": "builds the targets", "path": "ask627/w4/b1/b627.cjs", "source": "md5sum by W3"}, {"md5": "d9ee8c1a", "note": "the test, 34 checks", "path": "ask627/w4/b1/t627.cjs", "source": "md5sum by W3"}, {"md5": "5d76a5c3", "note": "test output, ALL PASS", "path": "ask627/w4/b1/out_t627.txt", "source": "md5sum by W3"}, {"md5": "f6ba8598", "note": "the node-filtered read of run 42373: the batch replies and the 9 unpriced question-round replies", "path": "ask627/w4/c3/out_c3_c4.txt", "source": "md5sum by W3; Wall 11811"}, {"md5": "82fd7ccb", "note": "the write script (notes name it 4355e7a5, a sha256 prefix); refuses on a live run, a moved base node or any failed check", "path": "ask627/w4/write/write627.sh", "source": "md5sum by W3; Wall 11815, 11818"}, {"md5": "d55bc883", "note": "the write's own output: both PUTs http 200; engine 560f01fb-f8fe-4be4-8498-68f3820eb6ac active, 423 nodes, params equal put, connections equal, changed Panel Tokens only; child b1d5a5bf-cc4d-40bb-baa8-3fb950d2cd65 active, 156 nodes